1	import type { NextRequest } from 'next/server'
2	import { NextResponse } from 'next/server'
3	import { z } from 'zod'
4	import { createPublicClient } from '@/lib/supabase/public'
5	import { publicBookingReadRatelimit } from '@/lib/rate-limit'
6	import { logger } from '@/lib/logger'
7	
8	interface Params {
9	  params: Promise<{ token: string }>
10	}
11	
12	export async function GET(request: NextRequest, { params }: Params) {
13	  const ip = request.headers.get('x-forwarded-for') ?? 'anonymous'
14	  const { success } = await publicBookingReadRatelimit.limit(ip)
15	  if (!success) {
16	    return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
17	  }
18	
19	  const { token } = await params
20	  if (!z.string().uuid().safeParse(token).success) {
21	    return NextResponse.json({ error: 'Invalid token' }, { status: 400 })
22	  }
23	
24	  try {
25	    const supabase = createPublicClient()
26	    const { data, error } = await supabase.rpc('public_get_booking_by_token', {
27	      p_token: token,
28	    })
29	
30	    if (error) {
31	      logger.error({ err: error, token }, 'public booking lookup failed')
32	      return NextResponse.json({ error: 'Failed to fetch booking' }, { status: 500 })
33	    }
34	
35	    if (!data) {
36	      return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
37	    }
38	
39	    return NextResponse.json({ data })
40	  } catch (err) {
41	    logger.error({ err }, 'public booking GET unexpected error')
42	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
43	  }
44	}
