if (parsed.data.action === 'offer') {
  if (entry.status !== 'active') {
    return NextResponse.json(
      { error: `Cannot offer slot — entry is already ${entry.status}` },
      { status: 409 }
    )
  }

  // M1: Verify the offered booking belongs to this studio before linking.
  // Without this check an attacker could link a cross-studio booking_id.
  const { data: booking, error: bookingLookupError } = await supabase
    .from('bookings')
    .select('id')
    .eq('id', parsed.data.booking_id)
    .eq('studio_id', authUser.studioId)
    .single()

  if (bookingLookupError || !booking) {
    return NextResponse.json({ error: 'Booking not found' }, { status: 404 })
  }

  const expiresAt = new Date()
  expiresAt.setHours(expiresAt.getHours() + parsed.data.offer_hours)

  const { data: updated, error: updateError } = await supabase
    .from('waitlist_entries')
    .update({
      status: 'offered',
      offered_booking_id: parsed.data.booking_id,
      offered_at: new Date().toISOString(),
      offered_expires_at: expiresAt.toISOString(),
